function initFooterFeedbackHandler(){let r=document.querySelectorAll(".feedback-option"),a=document.getElementById("footerFeedbackSection");var e=document.getElementById("feedbackToastSuccess"),t=document.getElementById("feedbackToastError");let d=new bootstrap.Toast(e),c=new bootstrap.Toast(t);r.forEach(o=>{o.addEventListener("click",()=>{r.forEach(e=>e.classList.remove("selected")),o.classList.add("selected");var e=o.querySelector("input"),t=(e.checked=!0,new FormData);t.append(`q${a.getAttribute("data-feedback-form-id")}:q1`,e.value),t.append(`form_email_${a.getAttribute("data-feedback-form-id")}_submit`,""),fetch(a.getAttribute("data-feedback-form-url"),{method:"POST",body:t}).then(e=>{(e.ok?(a.remove(),d):c).show()}).catch(e=>{console.error("Error submitting form:",e),alert("There was an error.")})})})}initFooterFeedbackHandler();